const input = require("fs").readFileSync(0, "utf8");

function allSubsets(nums) {
  const sorted = [...nums].sort((a, b) => a - b);
  const subsets = [];
  const path = [];

  // Decides on sorted[i]: first take it, then leave it out.
  function choose(i) {
    if (i === sorted.length) {
      subsets.push([...path]);
      return;
    }
    path.push(sorted[i]);
    choose(i + 1);
    path.pop();
    choose(i + 1);
  }

  choose(0);
  subsets.sort((a, b) => {
    if (a.length !== b.length) {
      return a.length - b.length;
    }
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i]) {
        return a[i] - b[i];
      }
    }
    return 0;
  });
  return subsets;
}

const [n, ...nums] = input.trim().split(/\s+/).map(Number);
for (const subset of allSubsets(nums.slice(0, n))) {
  console.log(subset.join(" "));
}

