#include <algorithm>
#include <iostream>
#include <vector>

using Subset = std::vector<int>;

// Decides on nums[i]: first take it, then leave it out.
void choose(const Subset& nums, std::size_t i, Subset& path, std::vector<Subset>& subsets) {
    if (i == nums.size()) {
        subsets.push_back(path);
        return;
    }
    path.push_back(nums[i]);
    choose(nums, i + 1, path, subsets);
    path.pop_back();
    choose(nums, i + 1, path, subsets);
}

std::vector<std::vector<int>> allSubsets(std::vector<int> nums) {
    std::sort(nums.begin(), nums.end());
    std::vector<Subset> subsets;
    Subset path;
    choose(nums, 0, path, subsets);
    // Vectors compare number by number with <, so only the size needs a rule.
    std::sort(subsets.begin(), subsets.end(), [](const Subset& a, const Subset& b) {
        if (a.size() != b.size()) {
            return a.size() < b.size();
        }
        return a < b;
    });
    return subsets;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    for (const std::vector<int>& subset : allSubsets(nums)) {
        for (std::size_t i = 0; i < subset.size(); i++) {
            std::cout << (i > 0 ? " " : "") << subset[i];
        }
        std::cout << "\n";
    }
    return 0;
}

