import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
    // Decides on nums[i]: first take it, then leave it out.
    static void choose(int[] nums, int i, List<Integer> path, List<List<Integer>> subsets) {
        if (i == nums.length) {
            subsets.add(new ArrayList<>(path));
            return;
        }
        path.add(nums[i]);
        choose(nums, i + 1, path, subsets);
        path.remove(path.size() - 1);
        choose(nums, i + 1, path, subsets);
    }

    static List<List<Integer>> allSubsets(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> subsets = new ArrayList<>();
        choose(nums, 0, new ArrayList<>(), subsets);
        subsets.sort((a, b) -> {
            if (a.size() != b.size()) {
                return Integer.compare(a.size(), b.size());
            }
            for (int i = 0; i < a.size(); i++) {
                int byNumber = Integer.compare(a.get(i), b.get(i));
                if (byNumber != 0) {
                    return byNumber;
                }
            }
            return 0;
        });
        return subsets;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] nums = new int[n];
        for (int i = 0; i < n; i++) {
            nums[i] = in.nextInt();
        }
        for (List<Integer> subset : allSubsets(nums)) {
            StringJoiner line = new StringJoiner(" ");
            for (int num : subset) {
                line.add(String.valueOf(num));
            }
            System.out.println(line);
        }
    }
}

