package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

func allSubsets(nums []int) [][]int {
	sort.Ints(nums)
	subsets := [][]int{}
	path := []int{}

	// Decides on nums[i]: first take it, then leave it out.
	var choose func(i int)
	choose = func(i int) {
		if i == len(nums) {
			subsets = append(subsets, append([]int{}, path...))
			return
		}
		path = append(path, nums[i])
		choose(i + 1)
		path = path[:len(path)-1]
		choose(i + 1)
	}

	choose(0)
	sort.Slice(subsets, func(a, b int) bool {
		x, y := subsets[a], subsets[b]
		if len(x) != len(y) {
			return len(x) < len(y)
		}
		for i := range x {
			if x[i] != y[i] {
				return x[i] < y[i]
			}
		}
		return false
	})
	return subsets
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	for _, subset := range allSubsets(nums) {
		parts := make([]string, len(subset))
		for i, num := range subset {
			parts[i] = strconv.Itoa(num)
		}
		fmt.Println(strings.Join(parts, " "))
	}
}

