import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

function allSubsets(nums: number[]): number[][] {
  const sorted = [...nums].sort((a, b) => a - b);
  const subsets: number[][] = [];
  const path: number[] = [];

  // Decides on sorted[i]: first take it, then leave it out.
  // Past the last number the lookup gives undefined, and the subset is done.
  function choose(i: number): void {
    const num = sorted[i];
    if (num === undefined) {
      subsets.push([...path]);
      return;
    }
    path.push(num);
    choose(i + 1);
    path.pop();
    choose(i + 1);
  }

  choose(0);
  subsets.sort((a, b) => {
    if (a.length !== b.length) {
      return a.length - b.length;
    }
    for (const [i, x] of a.entries()) {
      const y = b[i] ?? 0;
      if (x !== y) {
        return x - y;
      }
    }
    return 0;
  });
  return subsets;
}

const [n = 0, ...nums] = input.trim().split(/\s+/).map(Number);
for (const subset of allSubsets(nums.slice(0, n))) {
  console.log(subset.join(" "));
}
